    <section className="panel operational-position-settings"><h3>{isArabic ? "المواقع التشغيلية" : "Operational positions"}</h3><div className="settings-compact-grid">{config.positions.map((position) => <article className={positionEditorId === position.id ? "selected" : ""} key={position.id}><b>{position.labelAr || position.label}</b><span>{position.code} · {isArabic ? "أولوية" : "Priority"} {position.sortOrder}</span><small>{position.critical ? (isArabic ? "إلزامي" : "Mandatory") : (isArabic ? "مرن" : "Flexible")}</small><button type="button" className="secondary" onClick={() => setPositionEditorId(position.id)}>{isArabic ? "تعديل" : "Edit"}</button></article>)}</div><Field label={isArabic ? "اختر موقعًا للتعديل أو أضف موقعًا جديدًا" : "Choose a position to edit or add a new one"}><select aria-label={isArabic ? "اختر موقعًا للتعديل" : "Choose position to edit"} value={positionEditorId} onChange={(event) => setPositionEditorId(event.target.value)}><option value="">{isArabic ? "+ موقع جديد" : "+ New position"}</option>{config.positions.map((position) => <option key={position.id} value={position.id}>{position.code} · {position.labelAr || position.label}</option>)}</select></Field><form key={selectedPosition?.id || "new-position"} className="ops-inline-setting settings-editor-form" onSubmit={async (event) => { event.preventDefault(); const saved = await saveRecord("savePosition", event.currentTarget); if (saved && !selectedPosition) setPositionEditorId(""); }}><input name="code" defaultValue={selectedPosition?.code || ""} placeholder="Code" required readOnly={Boolean(selectedPosition)} /><input name="label" defaultValue={selectedPosition?.label || ""} placeholder="English label" /><input name="labelAr" defaultValue={selectedPosition?.labelAr || ""} placeholder="الاسم العربي" /><input name="sortOrder" defaultValue={selectedPosition?.sortOrder ?? 10} type="number" min="0" placeholder={isArabic ? "الأولوية" : "Priority"} /><label><input name="critical" type="checkbox" defaultChecked={Boolean(selectedPosition?.critical)} /> {isArabic ? "إلزامي" : "Mandatory"}</label><label><input name="requiresQualification" type="checkbox" defaultChecked={selectedPosition ? selectedPosition.requiresQualification : true} /> {isArabic ? "يتطلب تأهيل" : "Qualification required"}</label><div className="ops-form-actions"><button>{selectedPosition ? (isArabic ? "حفظ التعديل" : "Save changes") : (isArabic ? "إضافة الموقع" : "Add position")}</button>{selectedPosition && <button type="button" className="secondary" onClick={() => setPositionEditorId("")}>{isArabic ? "إلغاء" : "Cancel"}</button>}</div></form><h4>{isArabic ? "الحد الأدنى لكل شيفت" : "Minimum staffing per shift"}</h4><form className="ops-inline-setting settings-editor-form" onSubmit={(event) => { event.preventDefault(); saveRecord("saveRequirement", event.currentTarget); }}><select name="operationalPositionId" required defaultValue=""><option value="">{isArabic ? "اختر الموقع" : "Choose position"}</option>{config.positions.map((position) => <option key={position.id} value={position.id}>{position.labelAr || position.label}</option>)}</select><select name="shiftCode" defaultValue="AM"><option>AM</option><option>BW</option><option>PM</option></select><input name="minEmployees" type="number" min="0" defaultValue="1" /><input name="startTime" type="time" /><input name="endTime" type="time" /><input name="effectiveFrom" type="date" defaultValue="2000-01-01" /><button>{isArabic ? "حفظ التغطية" : "Save coverage"}</button></form></section>
