function RecognitionSettings({ config, settings, isArabic, busy, saveSetting, reload, setMessage }) {
  const [artwork, setArtwork] = useState(settings.RECOGNITION_ARTWORK_CONFIG || {});
  const global = artwork.global || {}; const monthly = artwork.monthly || {}; const hall = artwork.hall || {};
  const setGlobal = (key, value) => setArtwork((current) => ({ ...current, global: { ...(current.global || {}), [key]: value } }));
  const setMonthly = (key, value) => setArtwork((current) => ({ ...current, monthly: { ...(current.monthly || {}), [key]: value } }));
  const setHall = (key, value) => setArtwork((current) => ({ ...current, hall: { ...(current.hall || {}), [key]: value } }));
  const setEmployeeName = (id, value) => setArtwork((current) => ({ ...current, employeeNameOverrides: { ...(current.employeeNameOverrides || {}), [id]: value } }));
  async function uploadPhoto(employeeId, file) {
    if (!file) return; const form = new FormData(); form.set("file", file); form.set("employeeId", employeeId); form.set("documentType", "EMPLOYEE_PHOTO"); form.set("displayName", file.name);
    try { const payload = await fetch(`/api/operations/employees/${employeeId}/documents`, { method: "POST", body: form }).then(read); if (payload.document?.employeeId !== employeeId) throw new Error("Upload target verification failed"); setMessage(isArabic ? "تم تحديث صورة الموظف" : "Employee photo updated"); await reload(); }
    catch (error) { setMessage(error.message); }
  }
  const fontPicker = (value, onChange) => <select aria-label="Artwork font" value={value || '"Avenir Next", "Segoe UI", Arial, sans-serif'} onChange={(event) => onChange(event.target.value)}>{RECOGNITION_FONT_OPTIONS.map(([label, font]) => <option value={font} key={label}>{label}</option>)}</select>;
  return <div className="ops-settings-section recognition-settings"><header className="settings-content-head"><div><span>RECOGNITION ARTWORK</span><h2>{isArabic ? "موظف الشهر وقاعة السنة" : "Employee award and annual hall"}</h2><p>{isArabic ? "الثيم العام ثم إعدادات مستقلة لكل تصميم. الاسم اليدوي هنا لا يغير ملف الموظف." : "Use a shared theme with separate controls for each artwork. Display-name overrides do not alter employee records."}</p></div></header>
    <section className="panel form-grid"><h3>{isArabic ? "الثيم العام" : "Shared theme"}</h3><Field label={isArabic ? "الثيم" : "Theme"}><select aria-label={isArabic ? "الثيم" : "Theme"} value={artwork.theme || "CLASSIC"} onChange={(e) => { const presets = { CLASSIC: { primary: "#54209a", secondary: "#210067", accent: "#f8c800", background: "#ffffff", text: "#210067" }, ROYAL: { primary: "#173f7a", secondary: "#0c254d", accent: "#d6aa3b", background: "#fffdf6", text: "#0c254d" }, CELEBRATION: { primary: "#b61f55", secondary: "#4c164f", accent: "#f2b632", background: "#fff8fb", text: "#35153f" } }; setArtwork({ ...artwork, theme: e.target.value, global: { ...global, ...presets[e.target.value] } }); }}><option value="CLASSIC">Classic Billy Beez</option><option value="ROYAL">Royal Blue</option><option value="CELEBRATION">Celebration</option></select></Field><Field label={isArabic ? "رابط اللوجو" : "Logo URL"}><input value={global.logoUrl || "/bb-logo-fast.png"} onChange={(e) => setGlobal("logoUrl", e.target.value)} /></Field><Field label={isArabic ? "الخط العام" : "Global font"}>{fontPicker(global.fontFamily, (value) => setGlobal("fontFamily", value))}</Field>{[["primary", "اللون الأساسي", "Primary"],["secondary", "اللون الغامق", "Secondary"],["accent", "لون التمييز", "Accent"],["background", "الخلفية", "Background"],["text", "لون النص", "Text"]].map(([key, ar, en]) => <Field key={key} label={isArabic ? ar : en}><input type="color" value={global[key] || "#54209a"} onChange={(e) => setGlobal(key, e.target.value)} /></Field>)}</section>
    <section className="grid two">
      <article className="panel form-grid"><h3>{isArabic ? "إعدادات موظف الشهر" : "Monthly award settings"}</h3><Field label={isArabic ? "القالب الافتراضي" : "Default layout"}><select aria-label={isArabic ? "القالب الافتراضي" : "Default layout"} value={monthly.template || "T01"} onChange={(e) => setMonthly("template", e.target.value)}>{["T01","T02","T03","T04","T05"].map((item) => <option key={item}>{item}</option>)}</select></Field><TextSetting label={isArabic ? "جملة اللوجو" : "Brand tagline"} value={monthly.brandTagline} change={(v) => setMonthly("brandTagline", v)} /><TextSetting label={isArabic ? "العنوان الأول" : "Title line 1"} value={monthly.titleLine1} change={(v) => setMonthly("titleLine1", v)} /><TextSetting label={isArabic ? "العنوان الثاني" : "Title line 2"} value={monthly.titleLine2} change={(v) => setMonthly("titleLine2", v)} /><TextSetting label={isArabic ? "رسالة التهنئة" : "Congratulations line"} value={monthly.congratulations} change={(v) => setMonthly("congratulations", v)} hint="{firstName} / {name}" /><TextSetting label={isArabic ? "الرسالة" : "Message"} value={monthly.message} change={(v) => setMonthly("message", v)} hint="{firstName} / {name}" /><Field label={isArabic ? "خط الاسم" : "Name font"}>{fontPicker(monthly.nameFontFamily, (v) => setMonthly("nameFontFamily", v))}</Field><NumberSetting label={isArabic ? "حجم الاسم" : "Name size"} value={monthly.nameFontSize} change={(v) => setMonthly("nameFontSize", v)} min="16" max="58" /><NumberSetting label={isArabic ? "سمك الخط" : "Font weight"} value={monthly.nameFontWeight} change={(v) => setMonthly("nameFontWeight", v)} min="400" max="950" step="50" /><NumberSetting label={isArabic ? "المسافة بين الحروف" : "Letter spacing"} value={monthly.nameLetterSpacing} change={(v) => setMonthly("nameLetterSpacing", v)} min="-3" max="10" /><NumberSetting label={isArabic ? "أقصى عدد سطور للاسم" : "Maximum name lines"} value={monthly.nameMaxLines} change={(v) => setMonthly("nameMaxLines", v)} min="1" max="3" /><Field label={isArabic ? "لون الاسم" : "Name color"}><input type="color" value={monthly.nameColor || "#ffffff"} onChange={(e) => setMonthly("nameColor", e.target.value)} /></Field><TextSetting label={isArabic ? "خلفية الاسم (لون أو CSS gradient)" : "Name background"} value={monthly.nameBackground} change={(v) => setMonthly("nameBackground", v)} /><PhotoSettings values={monthly} setValue={setMonthly} isArabic={isArabic} /><Field label={isArabic ? "رسالة الجانب الأيسر" : "Left side message"}><textarea aria-label={isArabic ? "رسالة الجانب الأيسر" : "Left side message"} value={monthly.leftMessage || ""} onChange={(e) => setMonthly("leftMessage", e.target.value)} /></Field><Field label={isArabic ? "رسالة الجانب الأيمن" : "Right side message"}><textarea aria-label={isArabic ? "رسالة الجانب الأيمن" : "Right side message"} value={monthly.rightMessage || ""} onChange={(e) => setMonthly("rightMessage", e.target.value)} /></Field></article>
      <article className="panel form-grid"><h3>{isArabic ? "إعدادات قاعة السنة" : "Annual hall settings"}</h3>{[["slogan","الشعار الجانبي","Side slogan"],["title","عنوان القاعة","Hall title"],["subtitle","العنوان الفرعي","Subtitle"],["intro","مقدمة العنوان","Intro"],["messageTitle","عنوان الرسالة","Message heading"],["messageParagraph1","الرسالة الأولى","Message paragraph 1"],["messageParagraph2","الرسالة الثانية","Message paragraph 2"],["messageHighlight","رسالة التمييز","Highlighted message"],["messageFooter","خاتمة الرسالة","Message footer"],["signatureLabel","عنوان التوقيع","Signature label"],["signature","التوقيع","Signature"],["awaitingWinner","نص انتظار الفائز","Awaiting winner text"]].map(([key, ar, en]) => <TextSetting key={key} label={isArabic ? ar : en} value={hall[key]} change={(v) => setHall(key, v)} textarea={key.includes("Paragraph") || key === "messageFooter"} />)}<Field label={isArabic ? "خط أسماء الموظفين" : "Employee-name font"}>{fontPicker(hall.nameFontFamily, (v) => setHall("nameFontFamily", v))}</Field><NumberSetting label={isArabic ? "حجم الاسم" : "Name size"} value={hall.nameFontSize} change={(v) => setHall("nameFontSize", v)} min="8" max="20" /><NumberSetting label={isArabic ? "سمك الخط" : "Font weight"} value={hall.nameFontWeight} change={(v) => setHall("nameFontWeight", v)} min="400" max="950" step="50" /><NumberSetting label={isArabic ? "أقصى عدد سطور" : "Maximum name lines"} value={hall.nameMaxLines} change={(v) => setHall("nameMaxLines", v)} min="1" max="3" /><Field label={isArabic ? "لون الاسم" : "Name color"}><input type="color" value={hall.nameColor || "#210067"} onChange={(e) => setHall("nameColor", e.target.value)} /></Field><Field label={isArabic ? "لون الشهور الفردية" : "Odd-month color"}><input type="color" value={hall.oddMonthColor || "#54209a"} onChange={(e) => setHall("oddMonthColor", e.target.value)} /></Field><Field label={isArabic ? "لون الشهور الزوجية" : "Even-month color"}><input type="color" value={hall.evenMonthColor || "#f8c800"} onChange={(e) => setHall("evenMonthColor", e.target.value)} /></Field><TextSetting label={isArabic ? "لاحقة الفرع" : "Branch suffix"} value={hall.branchSuffix} change={(v) => setHall("branchSuffix", v)} /><Field label={isArabic ? "أسماء الشهور (12 سطر)" : "Month labels (12 lines)"}><textarea aria-label={isArabic ? "أسماء الشهور" : "Month labels"} value={(hall.monthLabels || []).join("\n")} onChange={(e) => setHall("monthLabels", e.target.value.split("\n").map((item) => item.trim()).filter(Boolean).slice(0, 12))} /></Field><Field label={isArabic ? "قيم الفوتر (الأيقونة|النص)" : "Footer values (icon|text)"}><textarea aria-label={isArabic ? "قيم الفوتر" : "Footer values"} value={(hall.values || []).map((item) => `${item.icon}|${String(item.text || [item.line1, item.line2].filter(Boolean).join("\n")).replaceAll("\n", " / ")}`).join("\n")} onChange={(e) => setHall("values", e.target.value.split("\n").map((line) => { const [icon, ...parts] = line.split("|"); return { icon: icon.trim(), text: parts.join("|").trim().replaceAll(" / ", "\n") }; }).filter((item) => item.icon && item.text))} /></Field><PhotoSettings values={hall} setValue={setHall} isArabic={isArabic} /></article>
    </section>
    <section className="panel"><h3>{isArabic ? "اسم وصورة الموظف في التصاميم" : "Artwork employee names and photos"}</h3><p className="muted">{isArabic ? "اكتب اسمًا مخصصًا للتصميم فقط، وارفع صورة الموظف من هنا. ترك الاسم فارغًا يستخدم الاسم الإنجليزي من الملف." : "Set an artwork-only name and upload the employee photo. A blank override uses the employee English name."}</p><div className="recognition-employee-settings">{config.employees.map((employee) => <article key={employee.id}><div><b>{employee.nameEn || employee.name}</b><small>{employee.documents?.length ? (isArabic ? "الصورة موجودة" : "Photo available") : (isArabic ? "لا توجد صورة" : "No photo")}</small></div><input value={artwork.employeeNameOverrides?.[employee.id] || ""} placeholder={isArabic ? "الاسم الظاهر في الجائزة" : "Artwork display name"} onChange={(e) => setEmployeeName(employee.id, e.target.value)} /><label className="button-like secondary">{isArabic ? "رفع / تغيير الصورة" : "Upload / replace photo"}<input hidden type="file" accept="image/jpeg,image/png,image/webp" onChange={(e) => uploadPhoto(employee.id, e.target.files?.[0])} /></label></article>)}</div></section>
    <button disabled={busy} onClick={() => saveSetting("RECOGNITION_ARTWORK_CONFIG", artwork, isArabic ? "تم حفظ إعدادات قوالب الجوائز" : "Recognition artwork settings saved")}>{isArabic ? "حفظ كل إعدادات الجوائز" : "Save all recognition settings"}</button>
  </div>;
}
function TextSetting({ label, value, change, hint, textarea = false }) { return <Field label={label}>{textarea ? <textarea aria-label={label} value={value || ""} onChange={(e) => change(e.target.value)} /> : <input value={value || ""} onChange={(e) => change(e.target.value)} />}{hint && <small>{hint}</small>}</Field>; }
function NumberSetting({ label, value, change, ...props }) { return <Field label={label}><input type="number" value={value ?? ""} onChange={(e) => change(Number(e.target.value))} {...props} /></Field>; }
function PhotoSettings({ values, setValue, isArabic }) { return <><Field label={isArabic ? "ملاءمة الصورة" : "Photo fit"}><select aria-label={isArabic ? "ملاءمة الصورة" : "Photo fit"} value={values.photoFit || "cover"} onChange={(e) => setValue("photoFit", e.target.value)}><option value="cover">Cover</option><option value="contain">Contain</option></select></Field><Field label={isArabic ? "موضع الصورة" : "Photo position"}><select aria-label={isArabic ? "موضع الصورة" : "Photo position"} value={values.photoPosition || "center"} onChange={(e) => setValue("photoPosition", e.target.value)}><option value="center">Center</option><option value="top">Top</option><option value="bottom">Bottom</option><option value="left">Left</option><option value="right">Right</option></select></Field></>; }

function MasterData({ config, settings, isArabic, busy, saveSetting, saveRecord, runRecordAction }) {
  const [catalogues, setCatalogues] = useState(settings.OPS_PLANNING_CATALOGS || { meals: [], partyRooms: [], stockItems: [] });
  const [editingPartner, setEditingPartner] = useState(null);
  const [editingCustomer, setEditingCustomer] = useState(null);
  const [editingNotice, setEditingNotice] = useState(null);
  const submitPartner = async (event) => {
    event.preventDefault();
    if (await saveRecord("savePartner", event.currentTarget)) setEditingPartner(null);
  };
  const submitCustomer = async (event) => {
    event.preventDefault();
    if (await saveRecord("saveCustomer", event.currentTarget)) setEditingCustomer(null);
  };
  return <div className="ops-settings-section">
    <h2>{isArabic ? "البيانات الأساسية" : "Planning master data"}</h2>
    <section className="grid two">
      <article className="panel ops-master-panel">
        <h3>{isArabic ? "الأكاديميات والمدارس" : "Academies and schools"}</h3>
        <div className="ops-master-list">{config.partners.map((item) => <div className="ops-master-row" key={item.id}><div><b>{item.name}</b><span>{item.supervisorName || "—"} · {item.supervisorPhone || "—"}</span></div><div><button type="button" disabled={busy} onClick={() => setEditingPartner(item)}>{isArabic ? "تعديل" : "Edit"}</button><button type="button" className="danger" disabled={busy} onClick={() => runRecordAction("deletePartner", { partnerId: item.id, branch: item.branch || "MOT" }, isArabic ? `حذف ${item.name}؟ الرحلات القديمة ستظل محفوظة.` : `Delete ${item.name}? Existing trips will remain saved.`)}>{isArabic ? "حذف" : "Delete"}</button></div></div>)}</div>
        <form key={editingPartner?.id || "new-partner"} className="form-grid" onSubmit={submitPartner}>
          {editingPartner && <input type="hidden" name="partnerId" value={editingPartner.id} />}
          <input name="name" required defaultValue={editingPartner?.name || ""} placeholder={isArabic ? "اسم الأكاديمية" : "Academy name"} />
          <input name="supervisorName" defaultValue={editingPartner?.supervisorName || ""} placeholder={isArabic ? "اسم المشرف" : "Supervisor"} />
          <input name="supervisorPhone" defaultValue={editingPartner?.supervisorPhone || ""} placeholder={isArabic ? "رقم المشرف" : "Phone"} />
          <textarea name="notes" defaultValue={editingPartner?.notes || ""} placeholder={isArabic ? "ملاحظات" : "Notes"} />
          <div className="ops-form-actions"><button disabled={busy}>{editingPartner ? (isArabic ? "حفظ التعديل" : "Save changes") : (isArabic ? "حفظ الأكاديمية" : "Save academy")}</button>{editingPartner && <button type="button" className="secondary" onClick={() => setEditingPartner(null)}>{isArabic ? "إلغاء" : "Cancel"}</button>}</div>
        </form>
      </article>
      <article className="panel ops-master-panel">
        <h3>{isArabic ? "عملاء أعياد الميلاد" : "Birthday customers"}</h3>
        <div className="ops-master-list">{config.customers.map((item) => <div className="ops-master-row" key={item.id}><div><b>{item.customerName}</b><span>{item.phone} · {item.childName || "—"}</span></div><div><button type="button" disabled={busy} onClick={() => setEditingCustomer(item)}>{isArabic ? "تعديل" : "Edit"}</button><button type="button" className="danger" disabled={busy} onClick={() => runRecordAction("deleteCustomer", { customerId: item.id, branch: item.branch || "MOT" }, isArabic ? `حذف ${item.customerName}؟ الحجوزات القديمة ستظل محفوظة.` : `Delete ${item.customerName}? Existing bookings will remain saved.`)}>{isArabic ? "حذف" : "Delete"}</button></div></div>)}</div>
        <form key={editingCustomer?.id || "new-customer"} className="form-grid" onSubmit={submitCustomer}>
          {editingCustomer && <input type="hidden" name="customerId" value={editingCustomer.id} />}
          <input name="customerName" required defaultValue={editingCustomer?.customerName || ""} placeholder={isArabic ? "اسم العميل" : "Customer"} />
          <input name="phone" required defaultValue={editingCustomer?.phone || ""} placeholder={isArabic ? "رقم الهاتف" : "Phone"} />
          <input name="childName" defaultValue={editingCustomer?.childName || ""} placeholder={isArabic ? "اسم الطفل" : "Child"} />
          <textarea name="notes" defaultValue={editingCustomer?.notes || ""} placeholder={isArabic ? "ملاحظات" : "Notes"} />
          <div className="ops-form-actions"><button disabled={busy}>{editingCustomer ? (isArabic ? "حفظ التعديل" : "Save changes") : (isArabic ? "حفظ العميل" : "Save customer")}</button>{editingCustomer && <button type="button" className="secondary" onClick={() => setEditingCustomer(null)}>{isArabic ? "إلغاء" : "Cancel"}</button>}</div>
        </form>
      </article>
    </section>
    <section className="grid two"><Catalogue title={isArabic ? "الوجبات" : "Meals"} value={catalogues.meals || []} onChange={(meals) => setCatalogues({ ...catalogues, meals })} /><Catalogue title={isArabic ? "الغرف" : "Party rooms"} value={(catalogues.partyRooms || []).map((item) => typeof item === "string" ? item : item.name)} onChange={(rooms) => setCatalogues({ ...catalogues, partyRooms: rooms.map((name) => ({ name, capacity: 0, active: true })) })} /></section><StockCatalogEditor value={catalogues.stockCatalog || {}} change={(stockCatalog) => setCatalogues({ ...catalogues, stockCatalog })} isArabic={isArabic} />
    <button disabled={busy} onClick={() => saveSetting("OPS_PLANNING_CATALOGS", catalogues)}>{isArabic ? "حفظ الكتالوجات" : "Save catalogues"}</button>
    <section className="panel"><h3>{isArabic ? "الإشعارات التشغيلية" : "Operational notices"}</h3><div className="ops-master-list">{config.notices?.map((item) => <div className={`ops-master-row ${item.active ? "" : "muted"}`} key={item.id}><div><b>{item.title}</b><span>{item.message}</span><small>{item.effectiveFrom} — {item.effectiveTo || "∞"} · {item.priority} · {item.active ? (isArabic ? "نشط" : "Active") : (isArabic ? "متوقف" : "Inactive")}</small></div><div><button type="button" disabled={busy} onClick={() => setEditingNotice(item)}>{isArabic ? "تعديل" : "Edit"}</button>{item.active ? <button type="button" className="danger" disabled={busy} onClick={() => runRecordAction("deleteNotice", { noticeId: item.id }, isArabic ? `إيقاف إشعار ${item.title}؟` : `Deactivate ${item.title}?`)}>{isArabic ? "حذف" : "Delete"}</button> : <button type="button" disabled={busy} onClick={() => runRecordAction("restoreNotice", { noticeId: item.id })}>{isArabic ? "استرجاع" : "Restore"}</button>}</div></div>)}</div><form key={editingNotice?.id || "new-notice"} className="form-grid" onSubmit={async (event) => { event.preventDefault(); if (await saveRecord("saveNotice", event.currentTarget)) setEditingNotice(null); }}>{editingNotice && <input type="hidden" name="noticeId" value={editingNotice.id} />}<input name="title" required defaultValue={editingNotice?.title || ""} placeholder={isArabic ? "عنوان الإشعار" : "Notice title"} /><textarea name="message" required defaultValue={editingNotice?.message || ""} placeholder={isArabic ? "نص الإشعار" : "Notice message"} /><select name="priority" defaultValue={editingNotice?.priority || "INFO"}><option value="INFO">Info</option><option value="WARNING">Warning</option><option value="CRITICAL">Critical</option></select><label>{isArabic ? "من تاريخ" : "From date"}<input name="effectiveFrom" type="date" required defaultValue={editingNotice?.effectiveFrom || ""} /></label><label>{isArabic ? "إلى تاريخ" : "To date"}<input name="effectiveTo" type="date" defaultValue={editingNotice?.effectiveTo || ""} /></label><label>{isArabic ? "من ساعة" : "From time"}<input name="startTime" type="time" defaultValue={editingNotice?.startTime || ""} /></label><label>{isArabic ? "إلى ساعة" : "To time"}<input name="endTime" type="time" defaultValue={editingNotice?.endTime || ""} /></label><div className="ops-form-actions"><button>{editingNotice ? (isArabic ? "حفظ التعديل" : "Save changes") : (isArabic ? "حفظ الإشعار" : "Save notice")}</button>{editingNotice && <button type="button" className="secondary" onClick={() => setEditingNotice(null)}>{isArabic ? "إلغاء" : "Cancel"}</button>}</div></form></section>
  </div>;
}
function BufferedTextarea({ ariaLabel, initialText, className = "", onText }) {
  const [text, setText] = useState(initialText);
  return <textarea aria-label={ariaLabel} className={className} value={text} onChange={(event) => { const next = event.target.value; setText(next); onText(next); }} />;
}
function Catalogue({ title, value, onChange }) { return <article className="panel"><h3>{title}</h3><BufferedTextarea ariaLabel={title} className="ops-long-textarea" initialText={value.join("\n")} onText={(text) => onChange(text.split("\n").map((item) => item.trim()).filter(Boolean))} /></article>; }
function StockCatalogEditor({ value, change, isArabic }) {
  const lines = (text) => text.split("\n").map((item) => item.trim()).filter(Boolean);
  const pairs = (text, kind) => lines(text).map((item) => { const [code, label = code] = item.split("|").map((part) => part.trim()); return kind === "color" ? { label: code, value: label || "#cccccc" } : { code: code.toUpperCase(), label }; });
  return <article className="panel form-grid"><h3>{isArabic ? "كتالوج الستوك" : "Stock catalogue"}</h3><p className="muted">{isArabic ? "سطر لكل قيمة. استخدم الاسم|القيمة للألوان والكود|الاسم لباقي القوائم. Trip وBirthday يظلان نوعين مرتبطين بالحجوزات." : "One value per line. Use label|value for colors and code|label for lists. Trip and Birthday remain booking-linked system types."}</p><Field label={isArabic ? "مقاسات الشرابات" : "Sock sizes"}><BufferedTextarea ariaLabel={isArabic ? "مقاسات الشرابات" : "Sock sizes"} initialText={(value.socksSizes || []).join("\n")} onText={(text) => change({ ...value, socksSizes: lines(text) })} /></Field><Field label={isArabic ? "ألوان الشرابات" : "Sock colors"}><BufferedTextarea ariaLabel={isArabic ? "ألوان الشرابات" : "Sock colors"} initialText={(value.socksColors || []).map((item) => `${item.label}|${item.value}`).join("\n")} onText={(text) => change({ ...value, socksColors: pairs(text, "color") })} /></Field><Field label={isArabic ? "خامات البريسلت" : "Bracelet materials"}><BufferedTextarea ariaLabel={isArabic ? "خامات البريسلت" : "Bracelet materials"} initialText={(value.braceletMaterials || []).map((item) => `${item.code}|${item.label}`).join("\n")} onText={(text) => change({ ...value, braceletMaterials: pairs(text) })} /></Field><Field label={isArabic ? "استخدامات البريسلت" : "Bracelet usages"}><BufferedTextarea ariaLabel={isArabic ? "استخدامات البريسلت" : "Bracelet usages"} initialText={(value.braceletUsages || []).map((item) => `${item.code}|${item.label}`).join("\n")} onText={(text) => { const parsed = pairs(text); const protectedItems = [{ code: "TRIP", label: "Trip", system: true }, { code: "BIRTHDAY", label: "Birthday", system: true }]; change({ ...value, braceletUsages: [...parsed.filter((item) => !["TRIP","BIRTHDAY"].includes(item.code)), ...protectedItems] }); }} /></Field><Field label={isArabic ? "حالات الرول" : "Roll styles"}><BufferedTextarea ariaLabel={isArabic ? "حالات الرول" : "Roll styles"} initialText={(value.rollStyles || []).map((item) => `${item.code}|${item.label}`).join("\n")} onText={(text) => change({ ...value, rollStyles: pairs(text) })} /></Field></article>;
}

function RulesSettings({ settings, criteria, isArabic, busy, saveSetting }) {
  const [attendance, setAttendance] = useState(settings.OPS_ATTENDANCE_RULES || {}); const [evaluation, setEvaluation] = useState(settings.OPS_EVALUATION_RULES || {}); const [leave, setLeave] = useState(settings.OPS_LEAVE_RULES || {}); const [rotation, setRotation] = useState(settings.OPS_ROTATION_RULES || {}); const [stock, setStock] = useState(settings.OPS_STOCK_RULES || {});
  return <div className="ops-settings-section"><h2>{isArabic ? "قواعد التشغيل" : "Operation rules"}</h2><section className="grid two"><RuleCard title={isArabic ? "الحضور" : "Attendance"}><Field label={isArabic ? "سماح التأخير بالدقائق" : "Late grace minutes"}><input type="number" value={attendance.lateGraceMinutes || 0} onChange={(e) => setAttendance({ ...attendance, lateGraceMinutes: Number(e.target.value) })} /></Field><Field label={isArabic ? "سماح الخروج المبكر" : "Early-leave grace"}><input type="number" value={attendance.earlyLeaveGraceMinutes || 0} onChange={(e) => setAttendance({ ...attendance, earlyLeaveGraceMinutes: Number(e.target.value) })} /></Field><label><input type="checkbox" checked={attendance.allowBulkExpectedTimes !== false} onChange={(e) => setAttendance({ ...attendance, allowBulkExpectedTimes: e.target.checked })} /> {isArabic ? "السماح بتطبيق المواعيد جماعيًا" : "Allow bulk expected times"}</label><label><input type="checkbox" checked={attendance.requireReasonAfterClose !== false} onChange={(e) => setAttendance({ ...attendance, requireReasonAfterClose: e.target.checked })} /> {isArabic ? "سبب التعديل بعد الإغلاق إلزامي" : "Require reason after close"}</label><button disabled={busy} onClick={() => saveSetting("OPS_ATTENDANCE_RULES", attendance)}>{isArabic ? "حفظ" : "Save"}</button></RuleCard><RuleCard title={isArabic ? "التقييم" : "Evaluation"}><p>{criteria?.label || (isArabic ? "لا توجد نسخة معايير نشطة" : "No active criteria version")}</p>{criteria?.criteria?.map((item) => <div className="row" key={item.id}><b>{item.labelAr || item.label}</b><span>{item.maxScore}</span></div>)}<Field label={isArabic ? "نظام الدرجة الافتراضية" : "Default score mode"}><select aria-label={isArabic ? "نظام الدرجة الافتراضية" : "Default score mode"} value={evaluation.defaultScoreMode || "FULL_UNREVIEWED"} onChange={(e) => setEvaluation({ ...evaluation, defaultScoreMode: e.target.value })}><option value="FULL_UNREVIEWED">10/10 · Unreviewed</option><option value="ZERO_UNREVIEWED">0/10 · Unreviewed</option></select></Field><Field label={isArabic ? "خصم الجزاء" : "Penalty deduction"}><input type="number" min="0" value={evaluation.penaltyDeduction ?? 25} onChange={(e) => setEvaluation({ ...evaluation, penaltyDeduction: Math.max(0, Number(e.target.value)) })} /></Field><Field label={isArabic ? "خصم الإجراء التوجيهي" : "Guidance deduction"}><input type="number" min="0" value={evaluation.guidanceDeduction ?? 15} onChange={(e) => setEvaluation({ ...evaluation, guidanceDeduction: Math.max(0, Number(e.target.value)) })} /></Field><label><input type="checkbox" checked={evaluation.requireReasonForDeduction !== false} onChange={(e) => setEvaluation({ ...evaluation, requireReasonForDeduction: e.target.checked })} /> {isArabic ? "سبب الخصم إلزامي" : "Deduction reason required"}</label><label><input type="checkbox" checked={evaluation.requireReviewBeforeClose !== false} onChange={(e) => setEvaluation({ ...evaluation, requireReviewBeforeClose: e.target.checked })} /> {isArabic ? "المراجعة قبل إغلاق اليوم" : "Require review before close"}</label><button disabled={busy} onClick={() => saveSetting("OPS_EVALUATION_RULES", evaluation)}>{isArabic ? "حفظ" : "Save"}</button></RuleCard><RuleCard title={isArabic ? "الإجازات والوقت" : "Leave and overtime"}><Field label={isArabic ? "ساعات اليوم الإضافي" : "Overtime hours per day"}><input type="number" value={leave.overtimeHoursPerDay || 8} onChange={(e) => setLeave({ ...leave, overtimeHoursPerDay: Number(e.target.value) })} /></Field><Field label={isArabic ? "تعويض العمل في العطلة" : "Holiday work credit"}><input type="number" value={leave.holidayWorkCreditDays || 2} onChange={(e) => setLeave({ ...leave, holidayWorkCreditDays: Number(e.target.value) })} /></Field><label><input type="checkbox" checked={leave.preventNegativeBalance !== false} onChange={(e) => setLeave({ ...leave, preventNegativeBalance: e.target.checked })} /> {isArabic ? "منع الرصيد السالب" : "Prevent negative balance"}</label><label><input type="checkbox" checked={leave.requireCoverageCheck !== false} onChange={(e) => setLeave({ ...leave, requireCoverageCheck: e.target.checked })} /> {isArabic ? "فحص التغطية قبل الاعتماد" : "Require coverage check"}</label><button disabled={busy} onClick={() => saveSetting("OPS_LEAVE_RULES", leave)}>{isArabic ? "حفظ" : "Save"}</button></RuleCard><RuleCard title={isArabic ? "تنبيهات المخزون" : "Stock alerts"}><Field label={isArabic ? "حد تنبيه المخزون المنخفض" : "Low-stock warning threshold"}><input type="number" min="0" value={stock.lowStockThreshold ?? 10} onChange={(e) => setStock({ ...stock, lowStockThreshold: Math.max(0, Number(e.target.value)) })} /></Field><button disabled={busy} onClick={() => saveSetting("OPS_STOCK_RULES", stock)}>{isArabic ? "حفظ" : "Save"}</button></RuleCard><RuleCard title={isArabic ? "الروتيشن" : "Rotation"}><Field label={isArabic ? "خلايا كل شيفت" : "Slots per shift"}><input type="number" value={rotation.slotsPerShift || 8} onChange={(e) => setRotation({ ...rotation, slotsPerShift: Number(e.target.value) })} /></Field><Field label={isArabic ? "الروتيشنز الإلزامية (كود ومفصولة بفاصلة)" : "Mandatory position codes (comma separated)"}><input value={(rotation.mandatoryPositionCodes || []).join(", ")} onChange={(e) => setRotation({ ...rotation, mandatoryPositionCodes: e.target.value.split(",").map((item) => item.trim().toUpperCase()).filter(Boolean) })} /></Field><label><input type="checkbox" checked={rotation.preserveManualLocks !== false} onChange={(e) => setRotation({ ...rotation, preserveManualLocks: e.target.checked })} /> {isArabic ? "حماية التعديلات اليدوية" : "Preserve manual locks"}</label><label><input type="checkbox" checked={rotation.avoidConsecutivePosition !== false} onChange={(e) => setRotation({ ...rotation, avoidConsecutivePosition: e.target.checked })} /> {isArabic ? "منع تكرار نفس الموقع في ساعات متتالية" : "Avoid consecutive position repeats"}</label><label><input type="checkbox" checked={rotation.distributeAvailableEmployees !== false} onChange={(e) => setRotation({ ...rotation, distributeAvailableEmployees: e.target.checked })} /> {isArabic ? "توزيع كل الموظفين المتاحين على المواقع" : "Distribute every available employee across positions"}</label><label><input type="checkbox" checked={rotation.optionalOnlyWhenFullyStaffed !== false} onChange={(e) => setRotation({ ...rotation, optionalOnlyWhenFullyStaffed: e.target.checked })} /> {isArabic ? "تطبيق الحد الأدنى للمواقع المرنة عند اكتمال الفريق فقط" : "Enforce flexible minimums only with full staffing"}</label><label><input type="checkbox" checked={rotation.excludeCashiers !== false} onChange={(e) => setRotation({ ...rotation, excludeCashiers: e.target.checked })} /> {isArabic ? "استبعاد الكاشير من الروتيشن" : "Exclude cashiers from rotation"}</label><label><input type="checkbox" checked={rotation.prioritizeMandatoryPositions !== false} onChange={(e) => setRotation({ ...rotation, prioritizeMandatoryPositions: e.target.checked })} /> {isArabic ? "أولوية المواقع الإلزامية" : "Prioritize mandatory positions"}</label><Field label={isArabic ? "المواقع المميزة بصريًا" : "Highlighted position codes"}><input value={(rotation.highlightedPositionCodes || []).join(", ")} onChange={(e) => setRotation({ ...rotation, highlightedPositionCodes: e.target.value.split(",").map((item) => item.trim().toUpperCase()).filter(Boolean) })} /></Field><h4>{isArabic ? "قاعدة رحلة الساعة 9" : "Early-trip shift rule"}</h4><label><input type="checkbox" checked={rotation.earlyTripRule?.enabled !== false} onChange={(e) => setRotation({ ...rotation, earlyTripRule: { ...(rotation.earlyTripRule || {}), enabled: e.target.checked } })} /> {isArabic ? "تفعيل القاعدة" : "Enable rule"}</label><Field label={isArabic ? "وقت الرحلة المحفز" : "Trip trigger time"}><input type="time" value={rotation.earlyTripRule?.triggerTime || "09:00"} onChange={(e) => setRotation({ ...rotation, earlyTripRule: { ...(rotation.earlyTripRule || {}), triggerTime: e.target.value } })} /></Field><Field label={isArabic ? "بداية الشيفت" : "Shift start"}><input type="time" value={rotation.earlyTripRule?.startTime || "09:00"} onChange={(e) => setRotation({ ...rotation, earlyTripRule: { ...(rotation.earlyTripRule || {}), startTime: e.target.value } })} /></Field><Field label={isArabic ? "نهاية الشيفت" : "Shift end"}><input type="time" value={rotation.earlyTripRule?.endTime || "17:00"} onChange={(e) => setRotation({ ...rotation, earlyTripRule: { ...(rotation.earlyTripRule || {}), endTime: e.target.value } })} /></Field><button disabled={busy} onClick={() => saveSetting("OPS_ROTATION_RULES", rotation)}>{isArabic ? "حفظ" : "Save"}</button></RuleCard></section></div>;
}
function RuleCard({ title, children }) { return <article className="panel form-grid"><h3>{title}</h3>{children}</article>; }
function Safety({ health, isArabic, reload }) { return <div className="ops-settings-section"><h2>{isArabic ? "السجل والسلامة" : "Audit and safety"}</h2><div className="grid three metrics"><article className="card metric"><div className="label">SQLite</div><div className="value">{health?.database?.integrity || "…"}</div></article><article className="card metric"><div className="label">{isArabic ? "حجم القاعدة" : "Database size"}</div><div className="value">{health ? `${(health.database.sizeBytes / 1024 / 1024).toFixed(1)} MB` : "…"}</div></article><article className="card metric"><div className="label">{isArabic ? "النسخ" : "Backups"}</div><div className="value">{health?.backups?.length || 0}</div></article></div><section className="grid two"><article className="panel"><h3>{isArabic ? "أحدث النسخ" : "Latest backups"}</h3>{health?.backups?.map((item) => <div className="row" key={item.name}><b>{item.name}</b><span>{(item.sizeBytes / 1024 / 1024).toFixed(1)} MB</span></div>)}</article><article className="panel"><h3>{isArabic ? "آخر تغييرات العمليات" : "Latest operations changes"}</h3>{health?.recentOperations?.map((item) => <div className="row" key={item.id}><span><b>{item.summary}</b><small>{item.user}</small></span><time>{new Date(item.createdAt).toLocaleString()}</time></div>)}</article></section><button onClick={reload}>{isArabic ? "إعادة الفحص" : "Run health check"}</button></div>; }
